startGuideActionCreate: "Erstelle",
startGuideActionMenu: "Wähle Menü",
startGuideActivity: "Aktivitäten sind Aufgaben&#44; die in Projekten geplant sind. <br/>Sie können einen Projektstrukturplan des Projektes erstellen. <br/>Es gibt keine Beschränkung für Ebenen / Phasen / Teilphasen / Aufgaben / Teilaufgaben.",
startGuideAffectation: "Eine Resource muss einem Projekt zugewiesen sein&#44; um dessen Elemente zu sehen. <br/>Die Zuweisung zu einem Projekt gibt automatisch auch Zugriff auf die Teilprojekte.",
startGuideClient: "Kunden sind Personen / Einheiten / Organe für die Sie arbeiten.<br/>Sie können intern oder extern zur eigenen Organisation stehen.",
startGuideContact: "Kontakte sind alle Personen&#44; mit denen sie in Kontakt stehen.",
startGuideFooter: "Dies sind die Hauptfunktionen. <br/>Sobald Sie damit vertraut sind&#44; sind Sie in der Lage auch die (zahlreichen) anderen Module für Ihre Projektsteuerung zu erkunden.",
startGuideImputation: "Resourcen erfassen die Ist-Arbeit unter 'Ist-Arbeit-Report' je Tag und Aktivität.<br/>Neuschätzungen der 'verbleibenden' Arbeit ermöglichen die Aktualisierung der Projektplanung mit dem tatsächlichen Fortschritt.",
startGuideIntro: "Hier eine kurze Einführung&#44; um die ersten Schritte mit ProjeQtOr zu erleichtern.<br>Folgen Sie diesen Schritten&#44; um die ersten Elemente zu konfigurieren.<br>Zögern Sie nicht&#44; die F1-Taste zu drücken&#44; um in das Benutzer-Handbuch zu gelangen und weitere Hilfe zu bekommen. <br>Gehen Sie zurück zur 'Heute'-Seite&#44; um zu dieser Starthilfe zu gelangen.",
startGuideMilestone: "Meilensteine sind Schlüsseltermine eines Projektes.<br/>Sie können eingehende (feste Meilensteine) oder Liefersergebnisse (gleitende Meilensteine) definieren.",
startGuidePlanning: "Planung zeigt eine Gantt Sicht.<br/>Um Aktivitäten zu planen&#44; müssen Resourcen mit Arbeitsplanwerten zu den Aktivitäten zugewiesen werden&#44; denn 'Planung' rechnet arbeitsgetrieben.<br/>Danach können sie Abhängigkeiten zwischen den Aufgaben (Vorgänger Element) und Meilensteinen festlegen. <br/>Nun können Sie die Plan-Kalkulation starten&#44; die alle Beschränkungen der Resourcen berücksichtigt.",
startGuideProject: "Projekt ist das Hauptelement in ProjeQtOr.<br/>Jedes Element ist zu einem Projekt verbunden.<br/>Zugriffsrechte sind ebenfalls auf Projektebene festgelegt.",
startGuideResource: "Resourcen sind Personen&#44; die an den Aufgaben arbeiten.<br/>Wenn Sie 'ist ein Nutzer' markieren&#44; dann ist die Resource in der Lage sich in ProjeQtOr einzuloggen.",
startGuideTicket: "Tickets können für jedes auftretende Ereignis genutzt werden&#44; wie z. B. Fehler&#44; Anforderungen&#44; usw. und einem Projekt zugeordnet werden.<br/>Sie können bei Bedarf einfach in Aktivitäten kopiert werden&#44; ohne dass die Daten neu erfasst werden müssen. Es kann auch die Verbindung zum Ursprungs-Element / Ticket erhalten werden.",
startGuideTitle: "Starthilfe",
startGuideUser: "Nutzer sind Personen&#44; die sich in ProjeQtOr einloggen können.<br/>Sie müssen ein Profil zugewiesen bekommen&#44; das die Zugriffsrechte regelt.",
